#pragma once
#include <stdint.h>
#include <pgmspace.h>

// 4-bit anti-aliased bitmap font, generated by tools/gen_fonts.py, stored in flash.
struct Glyph {
    uint16_t cp;      // unicode code point
    uint32_t off;     // byte offset into bits
    uint8_t  w, h;
    int8_t   x0, y0;  // bitmap origin relative to pen position on the baseline
    uint8_t  adv;     // horizontal advance
};

struct Font {
    const uint8_t* bits;
    const Glyph*   glyphs;
    uint16_t       count;
    uint8_t        asc, desc, px;
};
